-- 金额以分保存，订单保存下单时的菜品、价格与地址快照。
CREATE TABLE accounts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, version BIGINT NOT NULL DEFAULT 0, username VARCHAR(32) NOT NULL UNIQUE, display_name VARCHAR(40) NOT NULL, password_hash VARCHAR(256) NOT NULL, role VARCHAR(16) NOT NULL);
CREATE TABLE sessions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, version BIGINT NOT NULL DEFAULT 0, user_id BIGINT NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE addresses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, version BIGINT NOT NULL DEFAULT 0, user_id BIGINT NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT, contact_name VARCHAR(40) NOT NULL, phone VARCHAR(20) NOT NULL, detail VARCHAR(200) NOT NULL, label VARCHAR(20) NOT NULL);
CREATE TABLE menu_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, version BIGINT NOT NULL DEFAULT 0, category VARCHAR(20) NOT NULL, name VARCHAR(80) NOT NULL, description VARCHAR(300) NOT NULL, price_cents BIGINT NOT NULL, art_key VARCHAR(20) NOT NULL, is_demo BOOLEAN NOT NULL, available BOOLEAN NOT NULL);
CREATE TABLE food_orders (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, version BIGINT NOT NULL DEFAULT 0, user_id BIGINT NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT, request_key VARCHAR(36) NOT NULL, request_digest VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, subtotal_cents BIGINT NOT NULL, delivery_cents BIGINT NOT NULL, total_cents BIGINT NOT NULL, contact_name VARCHAR(40) NOT NULL, phone VARCHAR(20) NOT NULL, address_snapshot VARCHAR(200) NOT NULL, note VARCHAR(500) NOT NULL, is_demo BOOLEAN NOT NULL, UNIQUE(user_id, request_key));
CREATE TABLE order_lines (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, version BIGINT NOT NULL DEFAULT 0, order_id BIGINT NOT NULL REFERENCES food_orders(id) ON DELETE RESTRICT, menu_item_id BIGINT NOT NULL REFERENCES menu_items(id) ON DELETE RESTRICT, name VARCHAR(80) NOT NULL, unit_cents BIGINT NOT NULL, quantity INTEGER NOT NULL);
CREATE TABLE bookings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, version BIGINT NOT NULL DEFAULT 0, user_id BIGINT NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT, request_key VARCHAR(36) NOT NULL, request_digest VARCHAR(64) NOT NULL, service_type VARCHAR(12) NOT NULL, scene VARCHAR(30) NOT NULL, scheduled_at TIMESTAMP WITH TIME ZONE NOT NULL, people INTEGER NOT NULL, budget_cents BIGINT NOT NULL, quoted_total_cents BIGINT, status VARCHAR(32) NOT NULL, contact_name VARCHAR(40) NOT NULL, phone VARCHAR(20) NOT NULL, address_snapshot VARCHAR(200) NOT NULL, note VARCHAR(500) NOT NULL, UNIQUE(user_id, request_key));
CREATE INDEX ix_addresses_user ON addresses(user_id);
CREATE INDEX ix_food_orders_user ON food_orders(user_id);
CREATE INDEX ix_bookings_user ON bookings(user_id);
CREATE INDEX ix_sessions_user ON sessions(user_id);
CREATE INDEX ix_order_lines_order ON order_lines(order_id);
